mapper.select:
SELECT SUM(s.qty)::numeric / #{days} AS avg_daily_qty
FROM scm.sales_daily s
JOIN scm.location l ON l.location_id = s.location_id
WHERE s.sale_date BETWEEN #{fromDate} AND #{toDate}
AND s.sku = #{sku}
AND l.name = #{location}

SELECT s.sku, SUM(s.qty)::numeric / #{days} AS avg_daily_qty
FROM scm.sales_daily s
JOIN scm.location l ON l.location_id = s.location_id
WHERE s.sale_date BETWEEN #{fromDate} AND #{toDate}
AND l.name = #{location}
GROUP BY s.sku
ORDER BY avg_daily_qty
ASCDESC, s.sku
LIMIT #{limit}

SELECT oh.on_hand::numeric / NULLIF(d.qty::numeric / #{days}, 0) AS days_of_supply
FROM (
  SELECT SUM(i.on_hand) AS on_hand
  FROM scm.inventory_daily i
  JOIN scm.location l ON l.location_id = i.location_id
  WHERE i.snap_date = #{asOfDate}
  AND i.sku = #{sku}
  AND l.name = #{location}
) oh
CROSS JOIN (
  SELECT SUM(s.qty) AS qty
  FROM scm.sales_daily s
  JOIN scm.location l ON l.location_id = s.location_id
  WHERE s.sale_date BETWEEN #{fromDate} AND #{toDate}
  AND s.sku = #{sku}
  AND l.name = #{location}
) d

SELECT oh.sku, oh.on_hand::numeric / (d.qty::numeric / #{days}) AS days_of_supply
FROM (
  SELECT i.sku, SUM(i.on_hand) AS on_hand
  FROM scm.inventory_daily i
  JOIN scm.location l ON l.location_id = i.location_id
  WHERE i.snap_date = #{asOfDate}
  AND l.name = #{location}
  GROUP BY i.sku
) oh
JOIN (
  SELECT s.sku, SUM(s.qty) AS qty
  FROM scm.sales_daily s
  JOIN scm.location l ON l.location_id = s.location_id
  WHERE s.sale_date BETWEEN #{fromDate} AND #{toDate}
  AND l.name = #{location}
  GROUP BY s.sku
) d ON d.sku = oh.sku
WHERE d.qty > 0
ORDER BY days_of_supply
ASCDESC, oh.sku
LIMIT #{limit}

SELECT AVG(CASE WHEN i.on_hand = 0 THEN 1.0 ELSE 0.0 END) AS stockout_rate
FROM scm.inventory_daily i
JOIN scm.location l ON l.location_id = i.location_id
WHERE i.snap_date BETWEEN #{fromDate} AND #{toDate}
AND i.sku = #{sku}
AND l.name = #{location}

SELECT i.sku, AVG(CASE WHEN i.on_hand = 0 THEN 1.0 ELSE 0.0 END) AS stockout_rate
FROM scm.inventory_daily i
JOIN scm.location l ON l.location_id = i.location_id
WHERE i.snap_date BETWEEN #{fromDate} AND #{toDate}
AND l.name = #{location}
GROUP BY i.sku
ORDER BY stockout_rate
ASCDESC, i.sku
LIMIT #{limit}

mapper.sql:
SELECT f.sku, f.location_id, f.week_start, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f JOIN scm.location l ON l.location_id = f.location_id LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6
f.sku = #{sku} AND l.name = #{location}
GROUP BY f.sku, f.location_id, f.week_start, f.forecast_qty

FROM scm.inventory_daily i
JOIN scm.supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id
JOIN scm.location l ON l.location_id = i.location_id
WHERE i.snap_date = #{asOfDate}
  AND i.on_hand < p.safety_stock
AND i.sku = #{sku}
AND l.name = #{location}

mapper.select:
SELECT i.sku, l.name AS location_name, i.on_hand, p.safety_stock

ORDER BY i.sku, l.name
LIMIT #{limit}

mapper.sql:
FROM scm.inventory_daily i
JOIN scm.supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id
JOIN scm.location l ON l.location_id = i.location_id
WHERE i.snap_date = #{asOfDate}
  AND i.on_hand + i.in_transit <= p.reorder_point
AND i.sku = #{sku}
AND l.name = #{location}

mapper.select:
SELECT i.sku, l.name AS location_name, i.on_hand, i.in_transit, p.reorder_point

ORDER BY i.sku, l.name
LIMIT #{limit}
